function loadAppLogin() {
    if(window.jackeryLoginApp) {
        window.jackeryLoginApp.embedLogin()
    } else {
        setTimeout(() => {
            loadAppLogin()
        }, 200);
    }
}

document.addEventListener('DOMContentLoaded', function() {
    try {
        loadAppLogin()
    } catch (error) {
        console.log("jackeryLoginApp 未安装")
    }
});